 literal=next(ast.literal_eval(n.value) for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))
 assert literal==v['config']
 cls=next(n for n in t.body if isinstance(n,ast.ClassDef));methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
