 ci.body=[n for n in ci.body if not ((isinstance(n,ast.If) and (ast.unparse(n.test).startswith('click_view_objective ') or ast.unparse(n.test)==\"averaging_location "'!= '"'prediction'\")) or (isinstance(n,ast.Assign) and any(isinstance(x,ast.Attribute) and x.attr in ('click_view_objective','_click_objective_views') for x in n.targets)))]
 # Normalize treatment defaults for duplicate sources.
 for a,d in zip(ci.args.args[-len(ci.args.defaults):],ci.args.defaults):
  if a.arg=='coarse_view_treatment':d.value='reflect'
 assert ast.dump(ci)==ast.dump(pm['__init__']),(f,'constructor inherited')
 imports=[]
 for n in ast.walk(t):
  if isinstance(n,ast.Import):imports += [a.name.split('.')[0] for a in n.names]
  if isinstance(n,ast.ImportFrom):imports += [(n.module or '').split('.')[0]]
 assert set(imports)<={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
