 digest=hashlib.sha256(Path(f).read_bytes()).hexdigest();assert digest in v['note']
 # Apart from literal configuration/default choices, all four complete ASTs agree.
 norm=copy.deepcopy(t)
 norm.body=[n for n in norm.body if not (isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))]
 ni=next(n for n in norm.body if isinstance(n,ast.ClassDef)).body
 ni=next(n for n in ni if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 for a,d in zip(ni.args.args[-len(ni.args.defaults):],ni.args.defaults):
