for f,digest in expected.items():assert hashlib.sha256(Path(f).read_bytes()).hexdigest()==digest,(f,'immutable digest')
# Analytic objective distinction: no model/data execution.
for y in [0,1]:
 for a,b in [(0.9,0.1),(0.2,0.6),(0.7,0.7)]:
  bce=lambda q: -(y*math.log(q)+(1-y)*math.log1p(-q))
  assert 0.5*(bce(a)+bce(b))+1e-14>=bce(0.5*(a+b))
print('PASS full study schema; IDs; configs/defaults; inherited helpers/readout/forward/constructor; normalized ASTs; imports and named I/O; source hashes; immutable digests; analytic Jensen/null cases')
